'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var isnanf = require( '@stdlib/math/base/assert/is-nanf' );
var incrspace = require( '@stdlib/array/base/incrspace' );
var absf = require( '@stdlib/math/base/special/absf' );
var max = require( '@stdlib/math/base/special/maxn' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var tryRequire = require( '@stdlib/utils/try-require' );


// VARIABLES //

var gammaf = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( gammaf instanceof Error )
};


// FIXTURES //

var data1 = require( './fixtures/r/data1.json' );
var expected1 = require( './fixtures/r/expected1.json' );
var data2 = require( './fixtures/r/data2.json' );
var expected2 = require( './fixtures/r/expected2.json' );


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof gammaf, 'function', 'main export is a function' );
	t.end();
});

tape( 'if provided a negative integer, the function returns `NaN`', opts, function test( t ) {
	var values = incrspace( -1.0, -1000.0, -1.0 );
	var v;
	var i;

	for ( i = 0; i < values.length; i++ ) {
		v = gammaf( values[ i ] );
		t.strictEqual( isnanf( v ), true, 'returns expected value when provided ' + values[ i ] );
	}
	t.end();
});

tape( 'if provided negative infinity, the function returns `NaN`', opts, function test( t ) {
	var v = gammaf( NINF );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );
	t.end();
});

tape( 'if provided `NaN`, the function returns `NaN`', opts, function test( t ) {
	var v = gammaf( NaN );
	t.strictEqual( isnanf( v ), true, 'returns expected value' );
	t.end();
});

tape( 'if provided `-0`, the function returns negative infinity', opts, function test( t ) {
	var v = gammaf( -0.0 );
	t.strictEqual( v, NINF, 'returns expected value' );
	t.end();
});

tape( 'if provided `+0`, the function returns positive infinity', opts, function test( t ) {
	var v = gammaf( 0.0 );
	t.strictEqual( v, PINF, 'returns expected value' );
	t.end();
});

tape( 'if `x > 35.0400...`, the function returns positive infinity', opts, function test( t ) {
	var values = incrspace( 35.05, 100.0, 10.1234 );
	var v;
	var i;

	for ( i = 0; i < values.length; i++ ) {
		v = gammaf( values[ i ] );
		t.strictEqual( v, PINF, 'returns expected value when provided ' + values[ i ] );
	}
	t.end();
});

tape( 'if `x < -40.0019...`, the function returns zero', opts, function test( t ) {
	var values = incrspace( -40.002, -100.0, -10.1234 );
	var v;
	var i;

	for ( i = 0; i < values.length; i++ ) {
		v = gammaf( values[ i ] );
		t.strictEqual( v, 0.0, 'returns expected value when provided ' + values[ i ] );
	}
	t.end();
});

tape( 'the function evaluates the gamma function (positive integers)', opts, function test( t ) {
	var delta;
	var tol;
	var v;
	var i;

	for ( i = 0; i < data1.length; i++ ) {
		v = gammaf( data1[ i ] );
		delta = absf( v - expected1[ i ] );
		tol = 2.75e-5 * max( 1.0, absf( v ), absf( expected1[ i ] ) );
		t.ok( delta <= tol, 'within tolerance. x: ' + data1[ i ] + '. Value: ' + v + '. Expected: ' + expected1[ i ] + '. Tolerance: ' + tol + '.' );
	}
	t.end();
});

tape( 'the function evaluates the gamma function (decimal values)', opts, function test( t ) {
	var delta;
	var tol;
	var v;
	var i;

	for ( i = 0; i < data2.length; i++ ) {
		v = gammaf( data2[ i ] );
		delta = absf( v - expected2[ i ] );
		tol = 2.75e-5 * max( 1.0, absf( v ), absf( expected2[ i ] ) );
		t.ok( delta <= tol, 'within tolerance. x: ' + data2[ i ] + '. Value: ' + v + '. Expected: ' + expected2[ i ] + '. Tolerance: ' + tol + '.' );
	}
	t.end();
});

tape( 'if provided a positive integer, the function returns the factorial of (n-1)', opts, function test( t ) {
	t.strictEqual( gammaf( 4.0 ), 6.0, 'returns 6' );
	t.strictEqual( gammaf( 5.0 ), 24.0, 'returns 24' );
	t.strictEqual( gammaf( 6.0 ), 120.0, 'returns expected value' );
	t.end();
});

tape( 'the function uses a small value approximation for tiny positive x', opts, function test( t ) {
	var expected;
	var delta;
	var tol;
	var x;
	var v;

	x = 0.000009999999747378752;    // f32(1e-5) — triggers x < 1e-4 check
	v = gammaf( x );

	expected = 9.9999422e+4;
	delta = absf( v - expected );
	tol = 1.0;

	t.ok( delta < tol, 'within tolerance. x: ' + x + '. Value: ' + v +
		'. Expected: ' + expected + '. Tolerance: ' + tol + '.' );
	t.end();
});
